import React, { useState, useEffect } from 'react';
import { getStore2AllStocks, createStore2Stock, updateStore2Stock } from '../../services/stockService';

const StockOperations = () => {
    const [stocks, setStocks] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [selectedStock, setSelectedStock] = useState(null);

    const [stockForm, setStockForm] = useState({
        productCode: '',
        category: '',
        productName: '',
        size: '',
        color: '',
        quantity: 0,
        unitPrice: 0
    });

    useEffect(() => {
        fetchStocks();
    }, []);

    const fetchStocks = async () => {
        try {
            setLoading(true);
            setError(null);
            const response = await getStore2AllStocks();
            
            if (!response || !response.success) {
                throw new Error(response?.message || 'Stok verisi alınamadı');
            }
            
            setStocks(Array.isArray(response.data) ? response.data : []);
        } catch (err) {
            console.error('Stok verisi yüklenirken hata:', err);
            setError(err.message || 'Stok verileri yüklenirken bir hata oluştu');
            setStocks([]);
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            setError(null);
            // Form verilerini doğrula
            if (!stockForm.productCode || !stockForm.productName || !stockForm.category) {
                throw new Error('Lütfen tüm zorunlu alanları doldurun');
            }

            if (stockForm.quantity < 0 || stockForm.unitPrice < 0) {
                throw new Error('Miktar ve birim fiyat negatif olamaz');
            }

            let response;
            if (selectedStock) {
                response = await updateStore2Stock({ ...stockForm, id: selectedStock.id });
            } else {
                response = await createStore2Stock(stockForm);
            }

            if (!response || !response.success) {
                throw new Error(response?.message || 'İşlem başarısız oldu');
            }

            alert(selectedStock ? 'Stok başarıyla güncellendi' : 'Stok başarıyla oluşturuldu');
            fetchStocks();
            resetForm();
        } catch (err) {
            console.error('Form gönderimi sırasında hata:', err);
            setError(err.message || 'İşlem sırasında bir hata oluştu');
        }
    };

    const resetForm = () => {
        setStockForm({
            productCode: '',
            category: '',
            productName: '',
            size: '',
            color: '',
            quantity: 0,
            unitPrice: 0
        });
        setSelectedStock(null);
    };

    const handleEdit = (stock) => {
        setSelectedStock(stock);
        setStockForm({
            productCode: stock.productCode,
            category: stock.category,
            productName: stock.productName,
            size: stock.size,
            color: stock.color,
            quantity: stock.quantity,
            unitPrice: stock.unitPrice
        });
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-screen">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
            </div>
        );
    }

    return (
        <div className="p-6">
            <h1 className="text-3xl font-bold mb-8">Store 2 - Stok İşlemleri</h1>

            {/* Stok Ekleme/Güncelleme Formu */}
            <div className="bg-white rounded-lg shadow-md p-6 mb-8">
                <h2 className="text-xl font-bold mb-4">
                    {selectedStock ? 'Stok Güncelle' : 'Yeni Stok Ekle'}
                </h2>
                {error && (
                    <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
                        {error}
                    </div>
                )}
                <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input
                        type="text"
                        placeholder="Ürün Kodu"
                        className="border p-2 rounded"
                        value={stockForm.productCode}
                        onChange={(e) => setStockForm({...stockForm, productCode: e.target.value})}
                        required
                    />
                    <input
                        type="text"
                        placeholder="Kategori"
                        className="border p-2 rounded"
                        value={stockForm.category}
                        onChange={(e) => setStockForm({...stockForm, category: e.target.value})}
                        required
                    />
                    <input
                        type="text"
                        placeholder="Ürün Adı"
                        className="border p-2 rounded"
                        value={stockForm.productName}
                        onChange={(e) => setStockForm({...stockForm, productName: e.target.value})}
                        required
                    />
                    <input
                        type="text"
                        placeholder="Beden"
                        className="border p-2 rounded"
                        value={stockForm.size}
                        onChange={(e) => setStockForm({...stockForm, size: e.target.value})}
                    />
                    <input
                        type="text"
                        placeholder="Renk"
                        className="border p-2 rounded"
                        value={stockForm.color}
                        onChange={(e) => setStockForm({...stockForm, color: e.target.value})}
                    />
                    <input
                        type="number"
                        placeholder="Miktar"
                        className="border p-2 rounded"
                        value={stockForm.quantity}
                        onChange={(e) => setStockForm({...stockForm, quantity: parseInt(e.target.value) || 0})}
                        required
                        min="0"
                    />
                    <input
                        type="number"
                        placeholder="Birim Fiyat"
                        className="border p-2 rounded"
                        value={stockForm.unitPrice}
                        onChange={(e) => setStockForm({...stockForm, unitPrice: parseFloat(e.target.value) || 0})}
                        required
                        min="0"
                        step="0.01"
                    />
                    <div className="md:col-span-2 flex gap-2">
                        <button 
                            type="submit" 
                            className={`flex-1 p-2 rounded text-white ${
                                selectedStock ? 'bg-yellow-500 hover:bg-yellow-600' : 'bg-blue-500 hover:bg-blue-600'
                            }`}
                        >
                            {selectedStock ? 'Güncelle' : 'Ekle'}
                        </button>
                        {selectedStock && (
                            <button
                                type="button"
                                onClick={resetForm}
                                className="bg-gray-500 text-white p-2 rounded hover:bg-gray-600"
                            >
                                İptal
                            </button>
                        )}
                    </div>
                </form>
            </div>

            {/* Stok Listesi */}
            <div className="bg-white rounded-lg shadow-md p-6">
                <h2 className="text-xl font-bold mb-4">Stok Listesi</h2>
                {stocks.length === 0 ? (
                    <div className="text-center text-gray-500 py-4">
                        Henüz stok kaydı bulunmamaktadır.
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="min-w-full divide-y divide-gray-200">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Ürün Kodu
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Kategori
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Ürün Adı
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Beden
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Renk
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Miktar
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Birim Fiyat
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        İşlemler
                                    </th>
                                </tr>
                            </thead>
                            <tbody className="bg-white divide-y divide-gray-200">
                                {stocks.map((stock) => (
                                    <tr key={stock.id}>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.productCode}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.category}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.productName}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.size}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.color}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.quantity}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' })
                                                .format(stock.unitPrice)}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            <button
                                                onClick={() => handleEdit(stock)}
                                                className="text-blue-600 hover:text-blue-900"
                                            >
                                                Düzenle
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

export default StockOperations;
